import express from 'express';
import { authMiddleware } from './auth';
import { db } from './db';
import { validateBody } from './validate';
import { logger } from './logger';

const router = express.Router();

router.get('/users', authMiddleware, async (req, res) => {
  try {
    const users = await db.user.findMany({ select: { id: true, email: true, name: true } });
    res.json(users);
  } catch (err) {
    logger.error('GET /users failed', { err });
    res.status(500).json({ error: 'Internal error' });
  }
});

router.get('/users/:id', authMiddleware, async (req, res) => {
  try {
    const user = await db.user.findUnique({ where: { id: req.params.id } });
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
  } catch (err) {
    logger.error('GET /users/:id failed', { err });
    res.status(500).json({ error: 'Internal error' });
  }
});

router.post('/users', validateBody(['email', 'name', 'password']), async (req, res) => {
  try {
    const user = await db.user.create({ data: req.body });
    logger.info('User created', { userId: user.id });
    res.status(201).json(user);
  } catch (err) {
    logger.error('POST /users failed', { err });
    res.status(500).json({ error: 'Internal error' });
  }
});

router.put('/users/:id', authMiddleware, validateBody(['name', 'email']), async (req, res) => {
  try {
    const user = await db.user.update({ where: { id: req.params.id }, data: req.body });
    res.json(user);
  } catch (err) {
    logger.error('PUT /users/:id failed', { err });
    res.status(500).json({ error: 'Internal error' });
  }
});

router.delete('/users/:id', authMiddleware, async (req, res) => {
  try {
    await db.user.delete({ where: { id: req.params.id } });
    logger.info('User deleted', { userId: req.params.id });
    res.status(204).send();
  } catch (err) {
    logger.error('DELETE /users/:id failed', { err });
    res.status(500).json({ error: 'Internal error' });
  }
});

export default router;
```
